    /**
     * Method to retrieve the ExchangeRate via ExchangeRateFetchOneSummary
     * @param 	summary ExchangeRateFetchOneSummary 
     * @return 	ExchangeRateFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public ExchangeRate getExchangeRate( ExchangeRateFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ExchangeRateFetchOneSummary arg cannot be null" );
    	
    	ExchangeRate entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	ExchangeRateValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a ExchangeRate
        	// --------------------------------------
        	CompletableFuture<ExchangeRate> futureEntity = queryGateway.query(new FindExchangeRateQuery( new LoadExchangeRateFilter( summary.getExchangeRateId() ) ), ResponseTypes.instanceOf(ExchangeRate.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate ExchangeRate with id " + summary.getExchangeRateId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


