    /**
     * assign Bank on ExchangeRate
     * @param		command AssignBankToExchangeRateCommand	
     * @exception	ProcessingException
     */     
	public void assignBank( AssignBankToExchangeRateCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getExchangeRateId() );
		
		BankService childDelegate 	= BankService.getBankInstance();
		ExchangeRateService parentDelegate = ExchangeRateService.getExchangeRateInstance();			
		UUID childId = command.getAssignment().getBankId();
		Bank child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ExchangeRateValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Bank using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

